H.background();
const R1 = P.r1, R2 = P.r2, R3 = P.r3, Vb = P.volt;
const Rtot = R1 + R2 + R3;
const I = Vb / Math.max(Rtot, 0.1);
H.text("Series circuit:  R_total = R1 + R2 + R3", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const bx = 70, by = 90, w = H.W - 140, h = H.H - 200;
H.rect(bx, by, w, h, { stroke: H.colors.grid, width: 2, radius: 10 });
H.line(bx, by + h / 2 - 18, bx, by + h / 2 + 18, { color: H.colors.good, width: 5 });
H.line(bx - 7, by + h / 2 - 10, bx - 7, by + h / 2 + 10, { color: H.colors.good, width: 2 });
H.text("V = " + Vb.toFixed(1) + " V", bx - 4, by + h / 2 + 40, { color: H.colors.good, size: 12 });
const tops = [R1, R2, R3];
const cols = [H.colors.accent, H.colors.accent2, H.colors.violet];
const seg = w / 3;
for (let r = 0; r < 3; r++) {
  const rx0 = bx + r * seg + seg * 0.18, rxw = seg * 0.64, ry = by;
  let zz = [[rx0, ry]];
  for (let k = 0; k <= 6; k++) zz.push([rx0 + (k / 6) * rxw, ry + (k % 2 ? 11 : -11)]);
  zz.push([rx0 + rxw, ry]);
  H.path(zz, { color: cols[r], width: 3 });
  const Vr = I * tops[r];
  H.text("R" + (r + 1) + " = " + tops[r].toFixed(1) + " Ω", rx0, ry - 16, { color: cols[r], size: 12 });
  H.text("V" + (r + 1) + " = " + Vr.toFixed(2) + " V", rx0, ry + 30, { color: cols[r], size: 11 });
}
const per = 2 * (w + h);
const speed = H.clamp(40 + I * 60, 20, 200);
const N = 5;
for (let i = 0; i < N; i++) {
  const dd = ((t * speed + i * per / N) % per);
  let px, py;
  if (dd < w) { px = bx + dd; py = by; }
  else if (dd < w + h) { px = bx + w; py = by + (dd - w); }
  else if (dd < 2 * w + h) { px = bx + w - (dd - w - h); py = by + h; }
  else { px = bx; py = by + h - (dd - 2 * w - h); }
  H.circle(px, py, 5, { fill: H.colors.warn });
}
H.text("R_total = " + Rtot.toFixed(1) + " Ω    I = V/R_total = " + I.toFixed(3) + " A  (same in every resistor)", 24, 54, { color: H.colors.sub, size: 13 });
H.text("voltage drops add:  V1 + V2 + V3 = " + (I * Rtot).toFixed(2) + " V = battery V", 24, H.H - 22, { color: H.colors.good, size: 12 });
